 @Test public void transferQrCarriesOnlyTheWordsAndPrivateCodeIsHiddenAfterPause()throws Exception{
  local(v->{offer=AccountTransfer.begin(v,password.toCharArray());return true;});
  try(ActivityScenario<TransferActivity> screen=ActivityScenario.launch(TransferActivity.class)){await(screen,a->find(a.getWindow().getDecorView(),"Account move is pending")!=null);screen.onActivity(a->{try{java.lang.reflect.Field field=TransferActivity.class.getDeclaredField("offer");field.setAccessible(true);field.set(a,offer);java.lang.reflect.Method show=TransferActivity.class.getDeclaredMethod("showOffer");show.setAccessible(true);show.invoke(a);ImageView qr=image(a.getWindow().getDecorView());assertNotNull(qr);android.graphics.Bitmap bitmap=((android.graphics.drawable.BitmapDrawable)qr.getDrawable()).getBitmap();int[] pixels=new int[bitmap.getWidth()*bitmap.getHeight()];bitmap.getPixels(pixels,0,bitmap.getWidth(),0,0,bitmap.getWidth(),bitmap.getHeight());String scanned=new com.google.zxing.MultiFormatReader().decode(new com.google.zxing.BinaryBitmap(new com.google.zxing.common.HybridBinarizer(new com.google.zxing.RGBLuminanceSource(bitmap.getWidth(),bitmap.getHeight(),pixels)))).getText();TransferPhrase p=new TransferPhrase(a.getResources().openRawResource(R.raw.bip39_english));assertArrayEquals(offer.entropy,p.decode(scanned));assertFalse(scanned.contains(owner));assertTrue(contains(a.getWindow().getDecorView(),"1. "));}catch(Exception e){throw new AssertionError(e);}});screen.moveToState(Lifecycle.State.CREATED);screen.moveToState(Lifecycle.State.RESUMED);await(screen,a->find(a.getWindow().getDecorView(),"Account move is pending")!=null);screen.onActivity(a->{assertNull(image(a.getWindow().getDecorView()));assertFalse(contains(a.getWindow().getDecorView(),"1. "));});}
 }
 static ImageView image(View v){if(v instanceof ImageView&&"Private one-time account transfer QR".contentEquals(v.getContentDescription()))return (ImageView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){ImageView found=image(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 @Test public void deeplyNestedSignedTransferRecordIsRejectedBeforeChangingTheAccount()throws Exception{
  local(v->{byte[] key=new byte[32];new SecureRandom().nextBytes(key);File file=File.createTempFile("priperi-transfer-invalid-",".enc",context.getCacheDir());try{JSONObject metadata=new JSONObject().put("table","meta").put("id","meta").put("data",new JSONObject().put("contacts",new JSONObject()).put("settings",new JSONObject()));String nested="{\"x\":".repeat(30)+"0"+"}".repeat(30);JSONObject malformed=new JSONObject().put("table","messages").put("id",UUID.randomUUID().toString()).put("data",Crypto.b64(nested.getBytes(Crypto.UTF8)));try(OutputStream out=new FileOutputStream(file)){TransferArchive.write(out,key,TransferArchive.salt(),owner,v.identity().getString("fingerprint"),row->{row.accept(metadata.toString().getBytes(Crypto.UTF8));row.accept(malformed.toString().getBytes(Crypto.UTF8));},v.crypto()::signBackup,()->{});}try{Vault.verifyTransfer(file,key,v.account());fail("Deep record was accepted");}catch(IOException expected){assertTrue(expected.getMessage().contains("nesting"));}assertEquals(owner,v.account().getString("uid"));assertNull(target.account());assertNull(target.transferIn());return true;}finally{file.delete();Arrays.fill(key,(byte)0);}});
 }
 interface Ready{boolean ok(TransferActivity a);}static void await(ActivityScenario<TransferActivity> s,Ready r){for(int i=0;i<120;i++){boolean[] ok={false};s.onActivity(a->ok[0]=r.ok(a));if(ok[0])return;SystemClock.sleep(100);}fail("Transfer screen did not reach expected state");}
 static boolean contains(View v,String text){return v instanceof TextView&&((TextView)v).getText().toString().contains(text)||childrenContain(v,text);}static boolean childrenContain(View v,String text){if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(contains(((ViewGroup)v).getChildAt(i),text))return true;return false;}
 static View find(View v,String text){if(v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View match=find(((ViewGroup)v).getChildAt(i),text);if(match!=null)return match;}return null;}
 static int edits(View v){int count=v instanceof EditText?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)count+=edits(((ViewGroup)v).getChildAt(i));return count;}
 static AccessibilityNodeInfo node(AccessibilityNodeInfo n,String text,boolean editable){if(n==null)return null;if(editable?n.isEditable():text.equalsIgnoreCase(String.valueOf(n.getText()))&&n.isClickable())return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo match=node(n.getChild(i),text,editable);if(match!=null)return match;}return null;}
 static void click(String text){for(int i=0;i<120;i++){AccessibilityNodeInfo n=node(InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow(),text,false);if(n!=null){n.performAction(AccessibilityNodeInfo.ACTION_CLICK);return;}SystemClock.sleep(100);}Bundle diagnostic=new Bundle();diagnostic.putString("missingControl",text);diagnostic.putString("visibleControls",visibleControls(InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow()));InstrumentationRegistry.getInstrumentation().sendStatus(0,diagnostic);fail("Missing control: "+text);}
 static String visibleControls(AccessibilityNodeInfo n){if(n==null)return "";StringBuilder out=new StringBuilder();if(!n.isEditable()&&!n.isPassword()&&n.getText()!=null)out.append(n.getText()).append(" | ");for(int i=0;i<n.getChildCount();i++){out.append(visibleControls(n.getChild(i)));if(out.length()>2000)break;}return out.toString();}
 static void setPassword(String value){for(int i=0;i<120;i++){AccessibilityNodeInfo n=node(InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow(),null,true);if(n!=null){Bundle data=new Bundle();data.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);n.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,data);return;}SystemClock.sleep(100);}fail("Missing current-password field");}
